create type public.app_role as enum ('admin');
create table public.banners (accent text, active boolean default true, btn_text text, category text, created_at timestamptz default now(), description text, id bigint generated by default as identity primary key, image text, link text, sort_order numeric, subtitle text, title text, updated_at timestamptz default now());
create table public.berita (active boolean default true, author text, category text, content text, created_at timestamptz default now(), event_date text, featured boolean default false, id bigint generated by default as identity primary key, image text, location text, photo_source text, published_at timestamptz default now(), slug text unique, source_name text, source_url text, status text, submitter_email text, submitter_name text, summary text, title text, updated_at timestamptz default now());
create table public.community_applications (created_at timestamptz not null default now(), email text not null, full_name text not null, id bigint generated by default as identity primary key, interest text not null, reason text, whatsapp text not null);
create table public.digital_services (active boolean default true, category text, created_at timestamptz default now(), description text, featured boolean default false, id bigint generated by default as identity primary key, image text, price numeric, title text, updated_at timestamptz default now(), whatsapp text);
create table public.events (active boolean default true, allow_voucher boolean default false, banner_image text, category text, created_at timestamptz default now(), crew_active boolean default false, date text, date_end text, description text, featured boolean default false, guest_stars jsonb, id bigint generated by default as identity primary key, image text, location text, maps_url text, menu_items jsonb, name text, organizer text, organizer_ig text, payment_info jsonb, price numeric, prohibited_items jsonb, rundown jsonb, service_fee_percent numeric, slug text unique, time_end text, time_start text, title text, transportation_info jsonb, updated_at timestamptz default now(), visitors numeric);
create table public.influencers (active boolean default true, bio text, color text, color2 text, created_at timestamptz default now(), handle text, id bigint generated by default as identity primary key, instagram text, location text, name text, niches text[], photos text[], rate text, rating numeric, sort_order numeric, tiktok text, updated_at timestamptz default now(), verified boolean default false);
create table public.kamus_sunda (active boolean default true, category text, created_at timestamptz default now(), example text, id bigint generated by default as identity primary key, indonesia text, latin text, level text, sunda text, updated_at timestamptz default now());
create table public.kuliner (active boolean default true, category text, created_at timestamptz default now(), description text, facilities text, featured boolean default false, google_maps_url text, hours text, id bigint generated by default as identity primary key, image text, instagram text, location text, maps_embed_url text, name text, phone text, photos text, price_range text, rating numeric, reservasi_enabled boolean default false, slug text unique, updated_at timestamptz default now(), website text);
create table public.media_archive (id uuid primary key default gen_random_uuid(), manifest jsonb not null default '[]'::jsonb, updated_at timestamptz not null default now());
create table public.partners (active boolean default true, color text, created_at timestamptz default now(), id bigint generated by default as identity primary key, name text, sort_order numeric, updated_at timestamptz default now());
create table public.penginapan (active boolean default true, amenities text[], booking_enabled boolean default false, category text, created_at timestamptz default now(), description text, featured boolean default false, id bigint generated by default as identity primary key, image text, instagram text, location text, name text, price_per_night numeric, rating numeric, slug text unique, updated_at timestamptz default now());
create table public.perlombaan (active boolean default true, category text, created_at timestamptz default now(), date text, description text, featured boolean default false, fee numeric, id bigint generated by default as identity primary key, image text, location text, max_peserta numeric, name text, organizer text, prize numeric);
create table public.price_list (active boolean default true, category text, created_at timestamptz default now(), description text, id bigint generated by default as identity primary key, item text, price numeric, sort_order numeric, updated_at timestamptz default now());
create table public.promo_banners (active boolean default true, created_at timestamptz default now(), id bigint generated by default as identity primary key, image text, link text, sort_order numeric, updated_at timestamptz default now());
create table public.site_settings (key text primary key, updated_at timestamptz default now(), value text);
create table public.talents (active boolean default true, bio text, category text, created_at timestamptz default now(), featured boolean default false, id bigint generated by default as identity primary key, instagram text, name text, photo text, role text, sort_order numeric, tagline text, tags text[], updated_at timestamptz default now(), verified boolean default false, wa text);
create table public.transportasi (active boolean default true, asal text, created_at timestamptz default now(), description text, frekuensi text, id bigint generated by default as identity primary key, jam text, kode text, name text, tarif numeric, tujuan text, type text, updated_at timestamptz default now(), via text);
create table public.user_roles (id uuid primary key default gen_random_uuid(), role public.app_role not null, user_id uuid not null references auth.users(id) on delete cascade, unique (user_id, role));
create table public.vouchers (active boolean default true, applicable_type text, code text, created_at timestamptz default now(), description text, discount_type text, discount_value numeric, expiry_date text, id bigint generated by default as identity primary key, kuliner_id bigint, min_purchase numeric, mitra_id bigint, required_points numeric, title text, type text, updated_at timestamptz default now());
create table public.wisata (active boolean default true, category text, created_at timestamptz default now(), description text, entry_fee numeric, facilities text, google_maps_url text, id bigint generated by default as identity primary key, image text, instagram text, location text, maps_embed_url text, name text, opening_hours text, partner boolean default false, phone text, photos text, rating numeric, slug text unique, updated_at timestamptz default now(), website text);
create table public.event_tickets (active boolean default true, created_at timestamptz default now(), description text, event_id bigint references public.events(id) on delete cascade, id bigint generated by default as identity primary key, name text, price numeric, quota numeric, sale_end text, sale_start text, sold numeric, sort_order numeric);

create or replace function public.has_role(_user_id uuid, _role public.app_role)
returns boolean language sql stable security definer set search_path = public
as $$ select exists (select 1 from public.user_roles where user_id = _user_id and role = _role) $$;
grant execute on function public.has_role(uuid, public.app_role) to anon, authenticated;

grant select on public.user_roles to authenticated;
grant all on public.user_roles to service_role;
alter table public.user_roles enable row level security;
create policy "own roles readable" on public.user_roles for select to authenticated using (user_id = auth.uid());

do $$
declare t text;
begin
  foreach t in array array['banners','berita','community_applications','digital_services','events','event_tickets','influencers','kamus_sunda','kuliner','media_archive','partners','penginapan','perlombaan','price_list','promo_banners','site_settings','talents','transportasi','vouchers','wisata'] loop
    execute format('grant select, insert, update, delete on public.%I to authenticated', t);
    execute format('grant all on public.%I to service_role', t);
    execute format('alter table public.%I enable row level security', t);
    execute format('create policy "admin manage %s" on public.%I for all to authenticated using (public.has_role(auth.uid(), ''admin'')) with check (public.has_role(auth.uid(), ''admin''))', t, t);
  end loop;
  foreach t in array array['banners','digital_services','events','event_tickets','influencers','kamus_sunda','kuliner','partners','penginapan','perlombaan','price_list','promo_banners','talents','transportasi','vouchers','wisata'] loop
    execute format('grant select on public.%I to anon', t);
    execute format('create policy "public read %s" on public.%I for select to anon, authenticated using (true)', t, t);
  end loop;
end $$;

grant select (id,title,slug,summary,content,image,category,author,location,event_date,photo_source,source_name,source_url,status,featured,active,published_at,created_at,updated_at) on public.berita to anon;
create policy "public read berita" on public.berita for select to anon using (true);

grant insert on public.community_applications to anon;
create policy "anyone can apply" on public.community_applications for insert to anon, authenticated with check (true);
